def forecast(history: list[float], horizon: int, frequency: str) -> list[float]:
    import math
    if horizon <= 0:
        return []
    y = []
    for v in history:
        try:
            x = float(v)
            if math.isfinite(x):
                y.append(x)
        except Exception:
            pass
    if not y:
        return [0.0] * horizon

    def median(a):
        b = sorted(a)
        n = len(b)
        if not n:
            return 0.0
        return b[n // 2] if n % 2 else 0.5 * (b[n // 2 - 1] + b[n // 2])

    period = 7 if 'day' in str(frequency).lower() else 1
    if len(y) < 2 * period:
        return [median(y)] * horizon

    def make(train, steps, kind, weeks):
        m = len(train)
        start = max(0, m - weeks * period)
        overall = median(train[start:])
        recent_level = median(train[max(0, m - 2 * period):])
        ratio = recent_level / overall if abs(overall) > 1e-9 else 1.0
        ratio = max(0.75, min(1.25, ratio))
        out = []
        for k in range(steps):
            phase = (m + k) % period
            vals = [train[i] for i in range(start, m) if i % period == phase]
            if not vals:
                vals = train[start:]
            if kind == 'lag':
                value = train[m - period + (k % period)]
            elif kind == 'median':
                value = median(vals)
            elif kind == 'trimmed':
                s = sorted(vals)
                q = len(s) // 5
                core = s[q:len(s) - q] if q and len(s) > 2 * q else s
                value = sum(core) / len(core)
            elif kind == 'shrink':
                value = 0.8 * median(vals) + 0.2 * overall
            else:
                value = median(vals) * ratio
            out.append(max(0.0, value) if math.isfinite(value) else 0.0)
        return out

    candidates = []
    specs = [('lag', 1)]
    for weeks in (3, 5, 8, 12, 16):
        for kind in ('median', 'trimmed', 'shrink', 'adjusted'):
            specs.append((kind, weeks))
    block = min(14, max(period, horizon // 4))
    cuts = [len(y) - 3 * block, len(y) - 2 * block, len(y) - block]
    for kind, weeks in specs:
        errors = []
        fold_means = []
        for cut in cuts:
            if cut < max(2 * period, weeks * period // 2) or cut + block > len(y):
                continue
            pred = make(y[:cut], block, kind, weeks)
            fold = []
            for actual, fitted in zip(y[cut:cut + block], pred):
                fold.append(200.0 * abs(fitted - actual) / (abs(fitted) + abs(actual) + 1e-9))
            if fold:
                fold_means.append(sum(fold) / len(fold))
                errors.extend(fold)
        if errors:
            score = sum(errors) / len(errors) + 0.08 * (max(fold_means) - min(fold_means))
            candidates.append((score, kind, weeks))
    if not candidates:
        return make(y, horizon, 'median', 5)
    candidates.sort()
    chosen = [candidates[0]]
    for item in candidates[1:3]:
        if item[0] <= candidates[0][0] + 3.0:
            chosen.append(item)
    forecasts = [make(y, horizon, kind, weeks) for _, kind, weeks in chosen]
    weights = [1.0 / (score + 5.0) for score, _, _ in chosen]
    total = sum(weights)
    return [sum(weights[j] * forecasts[j][k] for j in range(len(forecasts))) / total for k in range(horizon)]

def forecast(history: list[float], horizon: int, frequency: str) -> list[float]:
    import math
    if horizon <= 0:
        return []
    y = []
    for v in history:
        try:
            x = float(v)
            if math.isfinite(x):
                y.append(x)
        except Exception:
            pass
    if not y:
        return [0.0] * horizon

    def median(a):
        b = sorted(a)
        n = len(b)
        if not n:
            return 0.0
        return b[n // 2] if n % 2 else 0.5 * (b[n // 2 - 1] + b[n // 2])

    def weighted_median(items):
        items = sorted(items)
        total = sum(w for _, w in items)
        acc = 0.0
        for value, weight in items:
            acc += weight
            if acc >= 0.5 * total:
                return value
        return items[-1][0]

    period = 7 if 'day' in str(frequency).lower() else 1

    def fallback(train, steps):
        m = len(train)
        out = []
        for k in range(steps):
            phase = (m + k) % period
            vals = [train[i] for i in range(max(0, m - 8 * period), m) if i % period == phase]
            out.append(max(0.0, median(vals if vals else train)))
        return out

    def make(train, steps, tail, neighbors):
        m = len(train)
        if m < tail + steps + period:
            return fallback(train, steps)
        current = train[-tail:]
        current_level = median(current)
        current_shape = [v - current_level for v in current]
        scale = median([abs(v) for v in current_shape]) + 1e-6
        matches = []
        for end in range(tail, m - steps + 1):
            segment = train[end - tail:end]
            level = median(segment)
            shape = [v - level for v in segment]
            distance = median([abs(shape[i] - current_shape[i]) for i in range(tail)]) / scale
            matches.append((distance, end, current_level - level))
        if not matches:
            return fallback(train, steps)
        matches.sort()
        selected = matches[:min(neighbors, len(matches))]
        out = []
        for k in range(steps):
            items = []
            for distance, end, shift in selected:
                value = train[end + k] + shift
                weight = 1.0 / (0.1 + distance)
                items.append((max(0.0, value), weight))
            out.append(weighted_median(items))
        return out

    block = min(14, max(period, horizon // 4))
    cuts = [len(y) - 3 * block, len(y) - 2 * block, len(y) - block]
    scored = []
    for tail in (7, 14, 21):
        for neighbors in (3, 5, 8):
            errors = []
            fold_scores = []
            for cut in cuts:
                if cut < tail + block + period or cut + block > len(y):
                    continue
                pred = make(y[:cut], block, tail, neighbors)
                fold = []
                for actual, fitted in zip(y[cut:cut + block], pred):
                    fold.append(200.0 * abs(fitted - actual) / (abs(fitted) + abs(actual) + 1e-9))
                if fold:
                    fold_scores.append(sum(fold) / len(fold))
                    errors.extend(fold)
            if errors:
                score = sum(errors) / len(errors) + 0.1 * (max(fold_scores) - min(fold_scores))
                scored.append((score, tail, neighbors))
    if not scored:
        return fallback(y, horizon)
    scored.sort()
    _, tail, neighbors = scored[0]
    return make(y, horizon, tail, neighbors)
